sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_evolution;
uniform float amzp_fractalType;
uniform float amzp_noiseType;
uniform float amzp_invert;
uniform float amzp_contrast;
uniform float amzp_brightness;
uniform float amzp_overflow;
uniform float amzp_subInfluence;
uniform float amzp_subScaling;
uniform float amzp_subRotation;
uniform float2 amzp_subOffset;
uniform float amzp_cycleEvo;
uniform float amzp_cycle;
uniform float amzp_seed;
uniform float amzp_fillLayer;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_complexity;
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 90.0) : p; }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        if (int(amzp_blendMode) == 4) return float4(min(b.rgb + f.rgb, float3(b.a)), b.a);
        if (int(amzp_blendMode) == 5) {
            if (b.a <= 0.0001) return b;
            float3 bu = b.rgb / b.a;
            float3 fu = f.a > 0.0001 ? f.rgb / f.a : float3(0.0);
            float3 c = mix(2.0 * bu * fu, 1.0 - 2.0 * (1.0 - bu) * (1.0 - fu), step(0.5, bu));
            return float4(mix(bu, clamp(c, 0.0, 1.0), f.a > 0.0001 ? clamp(amzp_alpha, 0.0, 1.0) : 0.0) * b.a, b.a);
        }
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float hash(float3 p) {
        p = fract(p * 0.3183099 + float3(0.1, 0.2, 0.3));
        p *= 17.0;
        return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
    }
    float valueNoise(float3 x, int nt, float period, float cycleOn) {
        float3 i = floor(x);
        float3 f = fract(x);
        if (nt == 0) f.xy = step(0.5, f.xy);
        else if (nt == 2) f.xy = f.xy * f.xy * (3.0 - 2.0 * f.xy);
        else if (nt == 3) f.xy = f.xy * f.xy * f.xy * (f.xy * (f.xy * 6.0 - 15.0) + 10.0);
        f.z = f.z * f.z * (3.0 - 2.0 * f.z);
        float z0 = i.z, z1 = i.z + 1.0;
        if (cycleOn > 0.5) { z0 = mod(z0, period); z1 = mod(z1, period); }
        return mix(
            mix(mix(hash(float3(i.x, i.y, z0)), hash(float3(i.x + 1.0, i.y, z0)), f.x),
                mix(hash(float3(i.x, i.y + 1.0, z0)), hash(float3(i.x + 1.0, i.y + 1.0, z0)), f.x), f.y),
            mix(mix(hash(float3(i.x, i.y, z1)), hash(float3(i.x + 1.0, i.y, z1)), f.x),
                mix(hash(float3(i.x, i.y + 1.0, z1)), hash(float3(i.x + 1.0, i.y + 1.0, z1)), f.x), f.y),
            f.z);
    }
    float2 rotate2(float2 v, float deg) {
        float c = cos(radians(deg)), s = sin(radians(deg));
        return float2(v.x * c - v.y * s, v.x * s + v.y * c);
    }
    float softClamp(float x) {
        float k = 0.25;
        float hi = x - (1.0 - k);
        if (hi > 0.0) x = (1.0 - k) + k * hi / (k + hi);
        float lo = k - x;
        if (lo > 0.0) x = k - k * lo / (k + lo);
        return x;
    }
    void amzRender() {
        float4 base = amzTexture(0, amzScreenNorm());
        float cover = (amzp_fillLayer>0.5) ? 1.0 : base.a;
        if (cover <= 0.0) { amzOutput = nmBlend(base, float4(0.0)); return; }
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float Hp = max(W.y / pxs(), 1.0);
        float aspect = W.x / max(W.y, 1.0);
        float2 off = float2(amzp_position.x, -amzp_position.y) / Hp;
        float2 ctr = float2(0.5 * aspect, 0.5);
        float2 amzLocal_pos = rotate2(float2(uv.x * aspect, uv.y) - ctr - off, amzp_angle) + ctr;
        float2 pivot = rotate2(-off, amzp_angle) + ctr;
        float2 sOff = float2(amzp_subOffset.x, -amzp_subOffset.y) / Hp;
        float2 strW = max(amzp_stretch, float2(1e-3));
        float cell = max(amzp_scale, 1e-3);
        float3 seedShift = floor(amzp_seed + 0.5) * float3(17.0, 29.0, 7.0);
        float cycleOn = (amzp_cycleEvo>0.5) ? 1.0 : 0.0;
        float period = max(floor(amzp_cycle + 0.5), 1.0);
        float zMul = cycleOn > 0.5 ? max(floor(amzp_subScaling + 0.5), 1.0) : max(amzp_subScaling, 1.0);
        float z = prog(amzp_evolution) / 360.0;
        float sum = 0.0, norm = 0.0, amp = 1.0;
        for (int i = 0; i < 8; i++) {
            float w = clamp(amzp_complexity - float(i), 0.0, 1.0) * amp;
            if (w > 0.0) {
                float3 q = float3(amzLocal_pos / (cell * strW), z) + seedShift;
                float v = valueNoise(q, int(amzp_noiseType), period, cycleOn);
                float t = v;
                if (int(amzp_fractalType) == 1) t = abs(2.0 * v - 1.0);
                else if (int(amzp_fractalType) == 2) t = sqrt(abs(2.0 * v - 1.0));
                else if (int(amzp_fractalType) == 3) { float a = 2.0 * v - 1.0; t = a * a; }
                if (int(amzp_fractalType) == 5) { sum = max(sum, t * w); norm = 1.0; }
                else { sum += t * w; norm += w; }
                if (int(amzp_fractalType) == 4) {
                    float v2 = valueNoise(q + float3(0.0, 0.0, 37.0), int(amzp_noiseType), period, cycleOn);
                    amzLocal_pos += (float2(v, v2) - 0.5) * cell;
                }
            }
            amp *= amzp_subInfluence;
            cell /= max(amzp_subScaling, 1.0);
            z *= zMul;
            period *= zMul;
            amzLocal_pos = rotate2(amzLocal_pos - pivot, amzp_subRotation) + pivot + sOff;
        }
        float n = sum / max(norm, 1e-4);
        n = (n - 0.5) * amzp_contrast + 0.5 + amzp_brightness;
        if (int(amzp_overflow) == 1) n = softClamp(n);
        else if (int(amzp_overflow) == 2) n = 1.0 - abs(mod(n, 2.0) - 1.0);
        n = clamp(n, 0.0, 1.0);
        if ((amzp_invert>0.5)) n = 1.0 - n;
        amzOutput = nmBlend(base, nmGradMap(float4(float3(n) * cover, cover)));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
